  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Altiratinib, a close structural analogue sharing the pyridyl ether, fluoro-substituted aniline, and amide/urea-like linker, achieved a brain:plasma ratio of 0.23 in mice and was classified as BBB-permeable, directly supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "GNE-7915, which shares pyridine, fluoro, CF3, and amide-containing polar aromatic features with the query, showed good CNS penetration in non-human primates with a Cub/Cup ratio of 0.69, supporting transfer of high brain penetration to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Poziotinib, containing a halogenated aniline and aryl ether similar to the query, demonstrated excellent brain permeability in mice with sustained brain concentrations above its IC50, supporting meaningful CNS exposure for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A related amide/CF3-containing compound achieved a rat brain:plasma ratio of 1.2, directly demonstrating good brain penetration for a molecule with comparable polar aromatic and halogenated features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "The highest-transfer analogue was confirmed by small-animal PET in rats to be highly CNS penetrant and fast clearing, providing strong independent evidence that this broad heteroaromatic scaffold class can cross the blood-brain barrier.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted pass: multiple high-transfer analogues with overlapping pyridine/ether/amide/urea and halogenated aryl motifs demonstrate meaningful BBB/CSF/brain penetration across rats, mice, non-human primates, and humans, with no contradictory direct evidence.",
